CREATE TABLE "pos"."fuel_cost_openings" (
  "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "branch_id" integer NOT NULL REFERENCES "pos"."branches"("id") ON DELETE RESTRICT,
  "product_id" integer NOT NULL REFERENCES "pos"."products"("id") ON DELETE RESTRICT,
  "effective_at" timestamptz NOT NULL,
  "liters" numeric(18,3) NOT NULL CHECK ("liters" >= 0),
  "unit_cost" numeric(18,6) NOT NULL CHECK ("unit_cost" >= 0),
  "note" text NOT NULL DEFAULT '',
  "created_at" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "fuel_cost_opening_branch_product_unique"
  ON "pos"."fuel_cost_openings" ("branch_id", "product_id");
ALTER TABLE "pos"."fuel_cost_openings" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON "pos"."fuel_cost_openings" FROM anon, authenticated;
ALTER TABLE "pos"."tank_refills"
  ADD COLUMN "net_cost_amount" numeric(24,6) CHECK ("net_cost_amount" >= 0);
COMMENT ON COLUMN "pos"."tank_refills"."net_cost_amount" IS
  'Confirmed acquisition value exclusive of recoverable VAT. NULL means historical or missing purchase basis.';
ALTER TABLE "pos"."tank_refills"
  ADD COLUMN "cost_product_id" integer REFERENCES "pos"."products"("id") ON DELETE RESTRICT;
UPDATE "pos"."staff_access_groups"
SET "menu_permissions" = "menu_permissions" || '["fuel_costing"]'::jsonb,
    "updated_at" = now()
WHERE "name" = 'ผู้จัดการ' AND "role" = 'manager'
  AND NOT ("menu_permissions" @> '["fuel_costing"]'::jsonb);
